import { useEffect, useState } from "react";
import Header from "./Header";
import Carousel from "./Carousel";
import Features from "./Features";
import ExamCta from "./ExamCta";
import AppDownload from "./AppDownload";
import BestCourses from "./BestCourses";
import Plans from "./Plans";
import ExploreDevices from "./ExploreDevices";
import StudySmarter from "./StudySmarter";
import SubFooter from "./SubFooter";
import Footer from "./Footer";
import api from "../services/api";
import type { HomeData, ListResponse } from "../types/home";

export default function Home() {
  const [home, setHome] = useState<HomeData | null>(null);

  useEffect(() => {
    api
      .get<ListResponse<HomeData>>("/homes", {
        params: {
          "populate[carousel][populate][0]": "image",
          "populate[carousel][populate][1]": "banner",
          "populate[feature][populate]": "image",
          "populate[cta]": true,
          "populate[app][populate][0]": "appStoreImage",
          "populate[app][populate][1]": "playStoreImage",
          "populate[app][populate][2]": "qrImage",
          "populate[app][populate][3]": "sideImage",
          "populate[courses][populate][items][populate][0]": "image",
          "populate[courses][populate][items][populate][1]": "features",
          "populate[plans][populate][tabs][populate][plans][populate]": "prices",
          "populate[plans][populate][tabs][populate][groups][populate][plans][populate]": "prices",
          "populate[plans][populate][tabs][populate][innerTabs][populate][plans][populate]": "prices",
          "populate[plans][populate][tabs][populate][innerTabs][populate][groups][populate][plans][populate]":
            "prices",
          "populate[explore][populate][0]": "image",
          "populate[explore][populate][1]": "background",
          "populate[studySmarter][populate]": "image",
          "populate[subFooter][populate][0]": "courses",
          "populate[subFooter][populate][1]": "centers",
          "populate[subFooter][populate][2]": "centerImage",
          "populate[subFooter][populate][3]": "qrImage",
          "populate[subFooter][populate][4]": "appStoreImage",
          "populate[subFooter][populate][5]": "playStoreImage",
        },
      })
      .then((payload) => setHome(payload.data?.[0] || null))
      .catch(() => setHome(null));
  }, []);

  return (
    <>
      <Header />
      <main>
        <Carousel slides={home?.carousel} />
        <Features items={home?.feature} />
        <ExamCta data={home?.cta} />
        <AppDownload data={home?.app} />
        <BestCourses data={home?.courses} />
        <Plans data={home?.plans} />
        <ExploreDevices data={home?.explore} />
        <StudySmarter data={home?.studySmarter} />
        <SubFooter data={home?.subFooter} />
      </main>
      <Footer />
    </>
  );
}
